import React from 'react';
import './PrinciplesSection.css';

const PrinciplesSection = () => {
    const principles = [
        {
            title: 'Осознанный подход',
            description: 'Мы стремимся к прозрачности и осознанности в работе, обеспечивая достоверность каждой оценки.'
        },
        {
            title: 'Высокие стандарты',
            description: 'Мы развиваем процессы, которые гарантируют качество и достоверность информации для наших пользователей.'
        },
        {
            title: 'Профессиональная этика',
            description: 'Мы придерживаемся строгих этических норм в нашей деятельности, сохраняя беспристрастность.'
        },
        {
            title: 'Беспристрастность',
            description: 'Наши оценки основаны исключительно на фактах и четких критериях, а не на личных предпочтениях.'
        }
    ];

    return (
        <section className="principles-section">
            <div className="principles-container">
                <h2 className="section-title">Наши принципы</h2>
                <div className="principles-grid">
                    {principles.map((principle, index) => (
                        <div key={index} className="principle-card">
                            <div className="principle-icon">
                                <span className="principle-number">0{index + 1}</span>
                            </div>
                            <h3 className="principle-title">{principle.title}</h3>
                            <p className="principle-description">{principle.description}</p>
                        </div>
                    ))}
                </div>
            </div>
        </section>
    );
};

export default PrinciplesSection;
